#define MAXT 1005

typedef struct {
    int l, r;
} Interval;

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        int n;
        scanf("%d", &n);

        Interval seg[MAXT];
        int maxR = 0;
        for (int i = 0; i < n; i++) {
            scanf("%d %d", &seg[i].l, &seg[i].r);
            if (seg[i].r > maxR) maxR = seg[i].r;
        }

        /* There are 9 possible positions of a 2x2 cloud on a 4x4 grid.
           Number cells 0..15, positions 0..8.
           cover[p][c] = 1 if position p rains on cell c.
        */
        int cover[9][16];
        memset(cover, 0, sizeof(cover));

        int p = 0;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                cover[p][r * 4 + c] = 1;
                cover[p][r * 4 + c + 1] = 1;
                cover[p][(r + 1) * 4 + c] = 1;
                cover[p][(r + 1) * 4 + c + 1] = 1;
                p++;
            }
        }

        /* DP over days.
           State: for each of 16 cells, days since last rain, capped at 6.
           We only care whether all cells stay <= 6 on all constrained days.
           Since 7^16 is impossible directly, note that the cloud position
           sequence only matters over the last 6 days.
           A cell is valid on a constrained day iff it was covered at least once
           in the last 6 days including today.
           Thus state can be represented by the last up to 6 cloud positions.

           There are at most 9^6 = 531441 states.
        */

        /* active[day] = whether constraint applies on this day */
        static unsigned char active[100000 + 5];
        memset(active, 0, maxR + 2);

        for (int i = 0; i < n; i++) {
            for (int d = seg[i].l; d <= seg[i].r; d++) active[d] = 1;
        }

        /* Encode last 6 positions in base 10, using digit 9 as "no day yet".
           10^6 = 1,000,000 states, manageable with bitsets/arrays.
        */
        const int BASE = 10;
        const int POW6 = 1000000;

        static unsigned char cur[1000000], nxt[1000000];
        memset(cur, 0, POW6);
        cur[999999] = 1; /* initial: six empty days before day 1 */

        int possible = 1;

        for (int day = 1; day <= maxR && possible; day++) {
            memset(nxt, 0, POW6);

            for (int state = 0; state < POW6; state++) {
                if (!cur[state]) continue;

                for (int np = 0; np < 9; np++) {
                    int ns = (state % 100000) * 10 + np;

                    if (active[day]) {
                        int ok = 1;

                        for (int cell = 0; cell < 16 && ok; cell++) {
                            int seen = cover[np][cell];
                            int tmp = state;

                            for (int k = 0; k < 5 && !seen; k++) {
                                int d = tmp % 10;
                                tmp /= 10;
                                if (d < 9 && cover[d][cell]) seen = 1;
                            }

                            if (!seen) ok = 0;
                        }

                        if (!ok) continue;
                    }

                    nxt[ns] = 1;
                }
            }

            possible = 0;
            for (int i = 0; i < POW6; i++) {
                if (nxt[i]) {
                    possible = 1;
                    break;
                }
            }

            memcpy(cur, nxt, POW6);
        }

        puts(possible ? "1" : "0");
    }

    return 0;
